def fibfib(n: int):
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 1

    fibfib_list = [0, 0, 1]

    for i in range(3, n + 1):
        next_value = fibfib_list[i - 1] + fibfib_list[i - 2] + fibfib_list[i - 3]
        fibfib_list.append(next_value)

    return fibfib_list[n]
